<script setup>import {reactive,watch} from 'vue';const props=defineProps({user:Object});const emit=defineEmits(['save']);const form=reactive({});watch(()=>props.user,value=>Object.assign(form,value||{}),{immediate:true});</script><template><form class="card profile-form" @submit.prevent="emit('save',{...form})"><h2>Thông tin cá nhân</h2><div class="form-grid"><label>Họ và tên<input v-model="form.fullName" required></label><label>Số điện thoại<input v-model="form.phone" pattern="0[0-9]{9}" required></label><label>Ngày sinh<input v-model="form.dateOfBirth" type="date"></label><label>Giới tính<select v-model="form.gender"><option value="">Chọn</option><option>Nam</option><option>Nữ</option><option>Khác</option></select></label></div><label>Địa chỉ<textarea v-model="form.address"></textarea></label><button class="btn primary">Lưu thay đổi</button></form></template>
